  1264  static enum lwan_http_status prepare_for_response(struct lwan_url_map *url_map,
  1265                                                    struct lwan_request *request)
  1266  {
  1267      struct lwan_request_parser_helper *helper = request->helper;
  1268
  1269      request->url.value += url_map->prefix_len;
  1270      request->url.len -= url_map->prefix_len;
  1271
  1272      if (url_map->flags & HANDLER_MUST_AUTHORIZE) {
  1273          if (!lwan_http_authorize(request, &helper->authorization,
  1274                                   url_map->authorization.realm,
  1275                                   url_map->authorization.password_file))
  1276              return HTTP_NOT_AUTHORIZED;
  1277      }
  1278
  1279      if (url_map->flags & HANDLER_REMOVE_LEADING_SLASH) {
  1280          while (*request->url.value == '/' && request->url.len > 0) {
  1281              ++request->url.value;
  1282              --request->url.len;
  1283          }
  1284      }
  1285
  1286      if (url_map->flags & HANDLER_PARSE_ACCEPT_ENCODING)
  1287          parse_accept_encoding(request);
  1288
  1289      if (lwan_request_get_method(request) == REQUEST_METHOD_POST) {
  1290          enum lwan_http_status status;
  1291
  1292          if (!(url_map->flags & HANDLER_HAS_POST_DATA)) {
  1293              /* FIXME: Discard POST data here? If a POST request is sent
  1294               * to a handler that is not supposed to handle a POST request,
  1295               * the next request in the pipeline will fail because the
  1296               * body of the previous request will be used as the next
  1297               * request itself. */
  1298              return HTTP_NOT_ALLOWED;
  1299          }
  1300
  1301          status = read_post_data(request);
  1302          if (UNLIKELY(status != HTTP_OK))
  1303              return status;
  1304      }
  1305
  1306      return HTTP_OK;
  1307  }
