  1309  static bool handle_rewrite(struct lwan_request *request)
  1310  {
  1311      struct lwan_request_parser_helper *helper = request->helper;
  1312
  1313      request->flags &= ~RESPONSE_URL_REWRITTEN;
  1314
  1315      parse_fragment_and_query(request, request->url.value + request->url.len);
  1316
  1317      helper->urls_rewritten++;
  1318      if (UNLIKELY(helper->urls_rewritten > 4)) {
  1319          lwan_default_response(request, HTTP_INTERNAL_ERROR);
  1320          return false;
  1321      }
  1322
  1323      return true;
  1324  }
